#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

cd "$(git rev-parse --show-toplevel)"
BUNDLE_ID="com.musclecuties.app"
TODAY="$(date +%Y-%m-%d)"
RECORD_DIR="docs/release-audit/$TODAY"
RECORD="$RECORD_DIR/OWNER_RELEASE_GATES_$TODAY.md"
mkdir -p "$RECORD_DIR"

GATES_PASSED=()
GATES_OPEN=()
gate_ok()   { GATES_PASSED+=("$1"); }
gate_open() { GATES_OPEN+=("$1"); }

banner "MuscleCuties · owner-only release gates (internal TestFlight)"

say "Everything here needs your Apple ID, your signing identity or your"
say "App Store Connect session. Nothing in this wizard archives, uploads,"
say "merges or writes any backend data: it only walks you through and records"
say "what you confirmed."
note "Bundle id: $BUNDLE_ID"
note "Record:     $RECORD"

# ── 1. App ID and capabilities ────────────────────────────────────────────
stage "App ID and capabilities"
say "The bundle id and the capabilities on the App ID must match what the"
say "shipped build actually uses. Entitlements in the repo ask for:"
note "  Sign in with Apple, Associated Domains (webcredentials:musclecuties.app),"
note "  keychain-access-groups, HealthKit (read-only; no HealthKit access groups)."
open_url "https://developer.apple.com/account/resources/identifiers/list"
step "Open the identifier for $BUNDLE_ID."
step "Confirm Sign in with Apple is enabled."
step "Confirm Associated Domains is enabled."
step "Confirm HealthKit is enabled."
step "Open App Services / Additional Capabilities and check nothing extra is on"
step "that the app does not ship (no Push, no iCloud, no Apple Pay)."
warn "Older notes say to remove the HealthKit capability for distribution."
warn "That contradicts the current build: the app reads sleep, steps and resting"
warn "heart rate through HealthKit. Removing the capability breaks Health sync."
warn "Treat that note as stale unless you deliberately drop HealthKit reads."
ask TEAM_ID "Apple Team ID (10 characters):"
if [[ ! "$TEAM_ID" =~ ^[A-Z0-9]{10}$ ]]; then
  warn "That does not look like a Team ID; record it by hand and check it on the portal."
  gate_open "Team ID format unconfirmed"
else
  note "Team $TEAM_ID recorded."
fi
if confirm "Do the App ID capabilities above match the shipped app?"; then
  gate_ok "App ID capabilities match"
else
  gate_open "App ID capabilities mismatch"
fi

# ── 2. Provisioning and signed entitlements ───────────────────────────────
stage "Provisioning profile and signed entitlements"
say "A clean archive is only trustworthy if the signed app carries the same"
say "entitlements as the repo. Signing is automatic by default, which can"
say "silently drop a capability the App ID does not have."
open_url "https://developer.apple.com/account/resources/profiles/list"
step "Confirm an App Store distribution profile exists for $BUNDLE_ID on Team $TEAM_ID."
step "In Xcode, select the MuscleCuties.UI project → Signing & Capabilities and"
step "confirm the team, the bundle id and the four capabilities."
step "After archiving, dump the signed entitlements from the .xcarchive's .app:"
note "  codesign -d --entitlements :- \"/path/to/MuscleCuties.UI.app\""
step "Confirm the dump contains:"
note "  com.apple.developer.applesignin = Default"
note "  com.apple.developer.associated-domains = webcredentials:musclecuties.app"
note "  com.apple.developer.healthkit = true"
note "  keychain-access-groups = <TeamID>.$BUNDLE_ID"
warn "The keychain group must be \$(AppIdentifierPrefix)$BUNDLE_ID, not a"
warn "hard-coded prefix from another team. A mismatch breaks the saved session"
warn "on a fresh install and is invisible in the simulator."
if confirm "Does the signed entitlements dump match the four values above?"; then
  gate_ok "Signed entitlements match"
else
  gate_open "Signed entitlements differ from the repo"
fi

# ── 3. App Privacy declaration ────────────────────────────────────────────
stage "App Privacy declaration"
say "The build sends and stores step averages and sleep hours on the backend,"
say "so Health and Fitness is collected, not merely read on-device."
open_url "https://appstoreconnect.apple.com/apps"
step "Open the MuscleCuties app → App Privacy."
step "Confirm Health and Fitness is declared, linked to the user's identity,"
step "and used for app functionality (not tracking, not advertising)."
step "Confirm the declared data types cover: step count, sleep hours, resting"
step "heart rate, workouts, and the cycle and injury data the app stores."
step "Confirm the privacy policy URL is present and reachable."
step "Compare against Platforms/iOS/PrivacyInfo.xcprivacy in this repo."
if confirm "Does the App Privacy declaration match what the app stores and PrivacyInfo.xcprivacy?"; then
  gate_ok "App Privacy declaration matches"
else
  gate_open "App Privacy declaration mismatch"
fi

# ── 4. In-app privacy copy for stored averages ────────────────────────────
stage "In-app privacy copy"
say "Testers will read Profile → Privacy before they connect Health. The copy"
say "must say what leaves the device and what Disconnect removes."
step "Install the release candidate on a physical device."
step "Open Profile → Privacy in Russian, then in English."
step "Confirm the Health card says steps and sleep are read from Apple Health,"
step "and that the stored daily averages are described where the app stores them."
step "Confirm Disconnect says what it stops and what stays."
step "Confirm no screen promises that health data never leaves the device."
if confirm "Is the privacy copy accurate in both languages, including stored averages?"; then
  gate_ok "In-app privacy copy accurate"
else
  gate_open "In-app privacy copy needs correction"
fi

# ── 5. Archive, upload, TestFlight internal group ─────────────────────────
stage "Archive, upload, TestFlight"
say "This is the only step that produces a distributable build."
warn "Only continue if you intend to upload to App Store Connect now."
step "In Xcode: Product → Archive with the Release configuration and"
step "the ios-arm64 device target (never iossimulator-arm64)."
step "Organizer → Distribute App → App Store Connect → Upload."
step "Answer export compliance consistently with the recorded decision (OD-5)."
step "Wait for processing, then open TestFlight and add the internal group."
step "Add the testers you intend to use for the beta, then install from TestFlight."
say ""
say "Then smoke the installed internal build, not the simulator:"
step "Cold launch, sign in, Today shows the calorie target."
step "Profile → Privacy: connect Apple Health, then refresh."
step "Open a workout day and confirm the session page loads."
if confirm "Did the build upload and install from TestFlight with the checks above passing?"; then
  gate_ok "Internal TestFlight build verified"
else
  gate_open "Archive/upload/TestFlight step not completed"
fi

# ── Record ────────────────────────────────────────────────────────────────
{
  printf '# Owner release gates — %s\n\n' "$TODAY"
  printf -- '- Bundle id: `%s`\n' "$BUNDLE_ID"
  printf -- '- Team ID: `%s`\n' "${TEAM_ID:-not recorded}"
  printf -- '- Branch: `%s` at `%s`\n\n' "$(git rev-parse --abbrev-ref HEAD)" "$(git rev-parse --short=7 HEAD)"
  printf '| Gate | Result |\n| --- | --- |\n'
  for gate in "${GATES_PASSED[@]}"; do printf '| %s | PASS |\n' "$gate"; done
  for gate in "${GATES_OPEN[@]}";    do printf '| %s | OPEN |\n' "$gate"; done
  printf '\nConfirmations are the owner'"'"'s; this record is evidence, not approval.\n'
} > "$RECORD"
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$RECORD"

finish
if (( ${#GATES_OPEN[@]} )); then
  warn "Open gates: ${#GATES_OPEN[@]}. Internal TestFlight stays NO-GO until they close."
else
  say "Every gate passed. Promotion still needs target checks and the owner's explicit approval."
fi
warn "This wizard never archives, uploads, merges or writes Beta data on its own."
